import { pathToFileURL } from 'node:url';

export function fib(n) {
  let a = 0;
  let b = 1;
  for (let i = 0; i < n; i++) {
    const t = a + b;
    a = b;
    b = t;
  }
  return a;
}

if (import.meta.url === pathToFileURL(process.argv[1]).href) {
  console.log(fib(40));
}
